#include <DHT.h>

// =====================================================
// SENSORS
// =====================================================

#define LDR_PIN   A0
#define TEMP_PIN  A1
#define AIR_PIN   A2
#define DHT_PIN   A3

#define DHTTYPE DHT11

DHT dht(DHT_PIN, DHTTYPE);


// =====================================================
// HC-SR04
// =====================================================

// Zone 1
#define TRIG1 2
#define ECHO1 4

// Zone 2
#define TRIG2 7
#define ECHO2 8

// Zone 3
#define TRIG3 12
#define ECHO3 13


// =====================================================
// LED / MOSFET OUTPUTS
// All are PWM pins on UNO R3
// =====================================================

// Zone 1
#define WHITE1  3
#define YELLOW1 5

// Zone 2
#define WHITE2  6
#define YELLOW2 9

// Zone 3
#define WHITE3  10
#define YELLOW3 11


// =====================================================
// SETTINGS
// =====================================================

#define OBJECT_DISTANCE 30.0

// Minimum brightness at night
#define MIN_BRIGHTNESS 20


// =====================================================
// HC-SR04 FUNCTION
// =====================================================

float readDistance(int trigPin, int echoPin)
{
  // Ensure trigger is LOW
    digitalWrite(trigPin, LOW);
      delayMicroseconds(5);

        // 15 microsecond trigger pulse
          digitalWrite(trigPin, HIGH);
            delayMicroseconds(15);
              digitalWrite(trigPin, LOW);

                // Wait for echo
                  unsigned long duration =
                        pulseIn(echoPin, HIGH, 30000UL);

                          // No echo received
                            if (duration == 0)
                              {
                                  return 999.0;
                                    }

                                      // Calculate distance in cm
                                        float distance =
                                              duration * 0.0343 / 2.0;

                                                return distance;
                                                }


                                                // =====================================================
                                                // SETUP
                                                // =====================================================

                                                void setup()
                                                {
                                                  Serial.begin(9600);

                                                    dht.begin();


                                                      // -------------------------------
                                                        // HC-SR04
                                                          // -------------------------------

                                                            pinMode(TRIG1, OUTPUT);
                                                              pinMode(ECHO1, INPUT);

                                                                pinMode(TRIG2, OUTPUT);
                                                                  pinMode(ECHO2, INPUT);

                                                                    pinMode(TRIG3, OUTPUT);
                                                                      pinMode(ECHO3, INPUT);


                                                                        // -------------------------------
                                                                          // LED / MOSFET
                                                                            // -------------------------------

                                                                              pinMode(WHITE1, OUTPUT);
                                                                                pinMode(YELLOW1, OUTPUT);

                                                                                  pinMode(WHITE2, OUTPUT);
                                                                                    pinMode(YELLOW2, OUTPUT);

                                                                                      pinMode(WHITE3, OUTPUT);
                                                                                        pinMode(YELLOW3, OUTPUT);


                                                                                          // -------------------------------
                                                                                            // Initial state
                                                                                              // -------------------------------

                                                                                                digitalWrite(TRIG1, LOW);
                                                                                                  digitalWrite(TRIG2, LOW);
                                                                                                    digitalWrite(TRIG3, LOW);

                                                                                                      analogWrite(WHITE1, 0);
                                                                                                        analogWrite(YELLOW1, 0);

                                                                                                          analogWrite(WHITE2, 0);
                                                                                                            analogWrite(YELLOW2, 0);

                                                                                                              analogWrite(WHITE3, 0);
                                                                                                                analogWrite(YELLOW3, 0);

                                                                                                                  delay(1000);
                                                                                                                  }


                                                                                                                  // =====================================================
                                                                                                                  // MAIN LOOP
                                                                                                                  // =====================================================

                                                                                                                  void loop()
                                                                                                                  {
                                                                                                                    // ===================================================
                                                                                                                      // LDR
                                                                                                                        // ===================================================

                                                                                                                          int lightValue = analogRead(LDR_PIN);


                                                                                                                            // Dark = brighter
                                                                                                                              // Bright = dimmer

                                                                                                                                int brightness =
                                                                                                                                      map(lightValue, 0, 1023, 255, 0);

                                                                                                                                        brightness =
                                                                                                                                              constrain(brightness, 0, 255);


                                                                                                                                                // ===================================================
                                                                                                                                                  // LM35
                                                                                                                                                    // ===================================================

                                                                                                                                                      int tempRaw =
                                                                                                                                                            analogRead(TEMP_PIN);

                                                                                                                                                              float voltage =
                                                                                                                                                                    tempRaw * (5.0 / 1023.0);

                                                                                                                                                                      float temperature =
                                                                                                                                                                            voltage * 100.0;


                                                                                                                                                                              // ===================================================
                                                                                                                                                                                // AIR QUALITY
                                                                                                                                                                                  // ===================================================

                                                                                                                                                                                    int airValue =
                                                                                                                                                                                          analogRead(AIR_PIN);


                                                                                                                                                                                            // ===================================================
                                                                                                                                                                                              // HUMIDITY
                                                                                                                                                                                                // ===================================================

                                                                                                                                                                                                  float humidity =
                                                                                                                                                                                                        dht.readHumidity();

                                                                                                                                                                                                          // If DHT11 fails
                                                                                                                                                                                                            if (isnan(humidity))
                                                                                                                                                                                                              {
                                                                                                                                                                                                                  humidity = 50.0;
                                                                                                                                                                                                                    }


                                                                                                                                                                                                                      // ===================================================
                                                                                                                                                                                                                        // BASE COLOR
                                                                                                                                                                                                                          // ===================================================

                                                                                                                                                                                                                            float whiteRatio = 0.50;
                                                                                                                                                                                                                              float yellowRatio = 0.50;


                                                                                                                                                                                                                                // ===================================================
                                                                                                                                                                                                                                  // TEMPERATURE
                                                                                                                                                                                                                                    // ===================================================

                                                                                                                                                                                                                                      if (temperature > 15.0)
                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                            float effect =
                                                                                                                                                                                                                                                    constrain(temperature, 15.0, 40.0);

                                                                                                                                                                                                                                                        effect =
                                                                                                                                                                                                                                                                (effect - 15.0) / 25.0;

                                                                                                                                                                                                                                                                    effect *= 0.30;

                                                                                                                                                                                                                                                                        whiteRatio += effect;
                                                                                                                                                                                                                                                                            yellowRatio -= effect;
                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                                                                  {
                                                                                                                                                                                                                                                                                      float effect =
                                                                                                                                                                                                                                                                                              constrain(temperature, 0.0, 15.0);

                                                                                                                                                                                                                                                                                                  effect =
                                                                                                                                                                                                                                                                                                          (15.0 - effect) / 15.0;

                                                                                                                                                                                                                                                                                                              effect *= 0.30;

                                                                                                                                                                                                                                                                                                                  yellowRatio += effect;
                                                                                                                                                                                                                                                                                                                      whiteRatio -= effect;
                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                          // ===================================================
                                                                                                                                                                                                                                                                                                                            // AIR QUALITY
                                                                                                                                                                                                                                                                                                                              // ===================================================

                                                                                                                                                                                                                                                                                                                                if (airValue > 300)
                                                                                                                                                                                                                                                                                                                                  {
                                                                                                                                                                                                                                                                                                                                      float airEffect =
                                                                                                                                                                                                                                                                                                                                              constrain(airValue, 300, 900);

                                                                                                                                                                                                                                                                                                                                                  airEffect =
                                                                                                                                                                                                                                                                                                                                                          (airEffect - 300.0) / 600.0;

                                                                                                                                                                                                                                                                                                                                                              airEffect *= 0.25;

                                                                                                                                                                                                                                                                                                                                                                  whiteRatio += airEffect;
                                                                                                                                                                                                                                                                                                                                                                      yellowRatio -= airEffect;
                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                          // ===================================================
                                                                                                                                                                                                                                                                                                                                                                            // HUMIDITY
                                                                                                                                                                                                                                                                                                                                                                              // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                if (humidity > 70.0)
                                                                                                                                                                                                                                                                                                                                                                                  {
                                                                                                                                                                                                                                                                                                                                                                                      float humidityEffect =
                                                                                                                                                                                                                                                                                                                                                                                              constrain(humidity, 70.0, 100.0);

                                                                                                                                                                                                                                                                                                                                                                                                  humidityEffect =
                                                                                                                                                                                                                                                                                                                                                                                                          (humidityEffect - 70.0) / 30.0;

                                                                                                                                                                                                                                                                                                                                                                                                              humidityEffect *= 0.35;

                                                                                                                                                                                                                                                                                                                                                                                                                  yellowRatio += humidityEffect;
                                                                                                                                                                                                                                                                                                                                                                                                                      whiteRatio -= humidityEffect;
                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                          // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                            // LIMIT COLOR VALUES
                                                                                                                                                                                                                                                                                                                                                                                                                              // =====================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                whiteRatio =
                                                                                                                                                                                                                                                                                                                                                                                                                                      constrain(whiteRatio, 0.0, 1.0);

                                                                                                                                                                                                                                                                                                                                                                                                                                        yellowRatio =
                                                                                                                                                                                                                                                                                                                                                                                                                                              constrain(yellowRatio, 0.0, 1.0);


                                                                                                                                                                                                                                                                                                                                                                                                                                                // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                  // CALCULATE FINAL BRIGHTNESS
                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                      int whiteBrightness =
                                                                                                                                                                                                                                                                                                                                                                                                                                                            brightness * whiteRatio;

                                                                                                                                                                                                                                                                                                                                                                                                                                                              int yellowBrightness =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    brightness * yellowRatio;


                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // READ ZONE 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            float distance1 =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  readDistance(TRIG1, ECHO1);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    delay(60);


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // READ ZONE 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            float distance2 =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  readDistance(TRIG2, ECHO2);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    delay(60);


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // READ ZONE 3
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            float distance3 =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  readDistance(TRIG3, ECHO3);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    delay(60);


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ZONE 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (distance1 <= OBJECT_DISTANCE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  analogWrite(WHITE1, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      analogWrite(YELLOW1, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                analogWrite(WHITE1, whiteBrightness);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    analogWrite(YELLOW1, yellowBrightness);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // ZONE 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (distance2 <= OBJECT_DISTANCE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    analogWrite(WHITE2, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        analogWrite(YELLOW2, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  analogWrite(WHITE2, whiteBrightness);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      analogWrite(YELLOW2, yellowBrightness);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ZONE 3
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (distance3 <= OBJECT_DISTANCE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      analogWrite(WHITE3, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          analogWrite(YELLOW3, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    analogWrite(WHITE3, whiteBrightness);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        analogWrite(YELLOW3, yellowBrightness);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // SERIAL MONITOR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // =====================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.println();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Serial.println("==============================");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Serial.print("LDR       : ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Serial.println(lightValue);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Serial.print("Brightness: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Serial.println(brightness);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Serial.print("Temperature: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Serial.print(temperature);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.println(" C");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Serial.print("Air       : ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Serial.println(airValue);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Serial.print("Humidity  : ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Serial.print(humidity);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Serial.println(" %");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Serial.print("Zone 1    : ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Serial.print(distance1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.println(" cm");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Serial.print("Zone 2    : ");
