                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Serial.println(" cm");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Serial.print("Zone 3    : ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Serial.print(distance3);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Serial.println(" cm");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Serial.println("==============================");


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Small delay before next cycle
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    delay(150);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

