#include <DHT.h>

// =====================================================
// SENSORS
// =====================================================

#define LDR_PIN   A0
#define TEMP_PIN  A1
#define AIR_PIN   A2
#define DHT_PIN   A3

#define DHTTYPE DHT11

DHT dht(DHT_PIN, DHTTYPE);


// =====================================================
// HC-SR04
// =====================================================

// Zone 1
#define TRIG1 2
#define ECHO1 4

// Zone 2
#define TRIG2 7
#define ECHO2 8

// Zone 3
#define TRIG3 12
#define ECHO3 13


// =====================================================
// LED / MOSFET OUTPUTS
// =====================================================

// Zone 1
#define WHITE1  3
#define YELLOW1 5

// Zone 2
#define WHITE2  6
#define YELLOW2 9

// Zone 3
#define WHITE3  10
#define YELLOW3 11


// =====================================================
// SETTINGS
// =====================================================

#define OBJECT_DISTANCE 30.0

// Minimum brightness
#define MIN_BRIGHTNESS 20


// =====================================================
// TIMING
// =====================================================

// DHT11 cannot be read continuously.
// Read it once every 1 second.
const unsigned long DHT_INTERVAL = 1000;

// Serial output interval
const unsigned long SERIAL_INTERVAL = 500;

// LED smooth transition interval
const unsigned long LED_INTERVAL = 5;

// Ultrasonic timeout
// 4000 us ≈ maximum useful range around 68 cm.
// Our detection distance is only 30 cm.
const unsigned long ECHO_TIMEOUT = 4000;


// =====================================================
// VARIABLES
// =====================================================

// DHT
float humidity = 50.0;

// Temperature
float temperature = 25.0;

// Sensor values
int lightValue = 0;
int airValue = 0;

// Distances
float distance1 = 999.0;
float distance2 = 999.0;
float distance3 = 999.0;


// =====================================================
// FILTERED SENSOR VALUES
// =====================================================

float filteredLDR = 0;
float filteredAir = 0;


// =====================================================
// LED CURRENT VALUES
// =====================================================

float currentWhite1 = 0;
float currentYellow1 = 0;

float currentWhite2 = 0;
float currentYellow2 = 0;

float currentWhite3 = 0;
float currentYellow3 = 0;


// =====================================================
// TIMERS
// =====================================================

unsigned long lastDHTRead = 0;
unsigned long lastSerial = 0;
unsigned long lastLEDUpdate = 0;


// =====================================================
// HC-SR04 FUNCTION
// =====================================================

float readDistance(int trigPin, int echoPin)
{
    // Make sure trigger is LOW
      digitalWrite(trigPin, LOW);
        delayMicroseconds(2);

          // HC-SR04 requires at least 10 us HIGH pulse
            digitalWrite(trigPin, HIGH);
              delayMicroseconds(10);
                digitalWrite(trigPin, LOW);

                  // Wait for echo
                    unsigned long duration =
                          pulseIn(echoPin, HIGH, ECHO_TIMEOUT);

                            // No echo
                              if (duration == 0)
                                {
                                      return 999.0;
                                }

                                  // Distance in cm
                                    float distance =
                                          duration * 0.0343 / 2.0;

                                            return distance;
}


// =====================================================
// SMOOTH LED FUNCTION
// =====================================================

float smoothValue(float current, float target)
{
    const float step = 18.0;

      if (current < target)
        {
              current += step;

                  if (current > target)
                        current = target;
        }
          else if (current > target)
            {
                  current -= step;

                      if (current < target)
                            current = target;
            }

              return current;
}


// =====================================================
// WRITE ALL LEDS
// =====================================================

void updateLEDs(
    int targetWhite1,
      int targetYellow1,
        int targetWhite2,
          int targetYellow2,
            int targetWhite3,
              int targetYellow3
)
{
    // Zone 1
      currentWhite1 =
            smoothValue(currentWhite1, targetWhite1);

              currentYellow1 =
                    smoothValue(currentYellow1, targetYellow1);


                      // Zone 2
                        currentWhite2 =
                              smoothValue(currentWhite2, targetWhite2);

                                currentYellow2 =
                                      smoothValue(currentYellow2, targetYellow2);


                                        // Zone 3
                                          currentWhite3 =
                                                smoothValue(currentWhite3, targetWhite3);

                                                  currentYellow3 =
                                                        smoothValue(currentYellow3, targetYellow3);


                                                          // Output PWM
                                                            analogWrite(WHITE1, (int)currentWhite1);
                                                              analogWrite(YELLOW1, (int)currentYellow1);

                                                                analogWrite(WHITE2, (int)currentWhite2);
                                                                  analogWrite(YELLOW2, (int)currentYellow2);

                                                                    analogWrite(WHITE3, (int)currentWhite3);
                                                                      analogWrite(YELLOW3, (int)currentYellow3);
}


// =====================================================
// SETUP
// =====================================================

void setup()
{
    Serial.begin(9600);

      dht.begin();


        // ---------------------------------------------------
          // HC-SR04
            // ---------------------------------------------------

              pinMode(TRIG1, OUTPUT);
                pinMode(ECHO1, INPUT);

                  pinMode(TRIG2, OUTPUT);
                    pinMode(ECHO2, INPUT);

                      pinMode(TRIG3, OUTPUT);
                        pinMode(ECHO3, INPUT);


                          digitalWrite(TRIG1, LOW);
                            digitalWrite(TRIG2, LOW);
                              digitalWrite(TRIG3, LOW);


                                // ---------------------------------------------------
                                  // LED / MOSFET
                                    // ---------------------------------------------------

                                      pinMode(WHITE1, OUTPUT);
                                        pinMode(YELLOW1, OUTPUT);

                                          pinMode(WHITE2, OUTPUT);
                                            pinMode(YELLOW2, OUTPUT);

                                              pinMode(WHITE3, OUTPUT);
                                                pinMode(YELLOW3, OUTPUT);


                                                  // ---------------------------------------------------
                                                    // Initial LED state
                                                      // ---------------------------------------------------

                                                        analogWrite(WHITE1, 0);
                                                          analogWrite(YELLOW1, 0);

                                                            analogWrite(WHITE2, 0);
                                                              analogWrite(YELLOW2, 0);

                                                                analogWrite(WHITE3, 0);
                                                                  analogWrite(YELLOW3, 0);


                                                                    // Initial analog values
                                                                      filteredLDR = analogRead(LDR_PIN);
                                                                        filteredAir = analogRead(AIR_PIN);


                                                                          // No long delay here
}


// =====================================================
// MAIN LOOP
// =====================================================

void loop()
{
    unsigned long now = millis();


      // ===================================================
        // LDR
          // ===================================================

            int rawLDR = analogRead(LDR_PIN);

              // Fast low-pass filter
                filteredLDR =
                      filteredLDR * 0.55 +
                            rawLDR * 0.45;

                              lightValue = (int)filteredLDR;


                                // Dark = brighter
                                  // Bright = dimmer

                                    int brightness =
                                          map(lightValue, 0, 1023, 255, 0);

                                            brightness =
                                                  constrain(brightness, 0, 255);


                                                    // ---------------------------------------------------
                                                      // Minimum night brightness
                                                        // ---------------------------------------------------

                                                          if (brightness > 0 && brightness < MIN_BRIGHTNESS)
                                                            {
                                                                  brightness = MIN_BRIGHTNESS;
                                                            }


                                                              // ===================================================
                                                                // LM35
                                                                  // ===================================================

                                                                    int tempRaw =
                                                                          analogRead(TEMP_PIN);

                                                                            float voltage =
                                                                                  tempRaw * (5.0 / 1023.0);

                                                                                    temperature =
                                                                                          voltage * 100.0;


                                                                                            // ===================================================
                                                                                              // AIR QUALITY
                                                                                                // ===================================================

                                                                                                  int rawAir =
