                                                                                                                                                                                                                                                    constrain(yellowBrightness, 0, 255);


                                                                                                                                                                                                                                                      // ===================================================
                                                                                                                                                                                                                                                        // HC-SR04
                                                                                                                                                                                                                                                          // ===================================================

                                                                                                                                                                                                                                                            // Read each sensor sequentially.
                                                                                                                                                                                                                                                              // No 60 ms delays.
