                                                                                                                                                                                                                                                                                                          int targetYellow2 = yellowBrightness;

                                                                                                                                                                                                                                                                                                            int targetWhite3 = whiteBrightness;
                                                                                                                                                                                                                                                                                                              int targetYellow3 = yellowBrightness;


