                                                                                                                                                                                                                                                                                                                                                  targetWhite3 = 0;
                                                                                                                                                                                                                                                                                                                                                      targetYellow3 = 0;
                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                              // ===================================================
                                                                                                                                                                                                                                                                                                                                                // UPDATE LEDS
                                                                                                                                                                                                                                                                                                                                                  // ===================================================

                                                                                                                                                                                                                                                                                                                                                    if (now - lastLEDUpdate >= LED_INTERVAL)
                                                                                                                                                                                                                                                                                                                                                      {
                                                                                                                                                                                                                                                                                                                                                            lastLEDUpdate = now;

                                                                                                                                                                                                                                                                                                                                                                updateLEDs(
                                                                                                                                                                                                                                                                                                                                                                        targetWhite1,
                                                                                                                                                                                                                                                                                                                                                                              targetYellow1,
                                                                                                                                                                                                                                                                                                                                                                                    targetWhite2,
                                                                                                                                                                                                                                                                                                                                                                                          targetYellow2,
                                                                                                                                                                                                                                                                                                                                                                                                targetWhite3,
                                                                                                                                                                                                                                                                                                                                                                                                      targetYellow3
                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                      }


                                                                                                                                                                                                                                                                                                                                                        // ===================================================
                                                                                                                                                                                                                                                                                                                                                          // SERIAL MONITOR
                                                                                                                                                                                                                                                                                                                                                            // ===================================================

                                                                                                                                                                                                                                                                                                                                                              if (now - lastSerial >= SERIAL_INTERVAL)
                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                      lastSerial = now;

                                                                                                                                                                                                                                                                                                                                                                          Serial.println();
